use super::*;
use std::io::Read;
use tungstenite::protocol::Role;

#[test]
fn a_retained_routing_target_keeps_transport_capacity_until_the_descriptor_closes() {
    let relay = Relay::new(crate::Config {
        max_connections: 1,
        ping_interval_secs: 0,
        ..crate::Config::default()
    })
    .unwrap();
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let client = std::net::TcpStream::connect(listener.local_addr().unwrap()).unwrap();
    client
        .set_read_timeout(Some(Duration::from_secs(1)))
        .unwrap();
    let (stream, _) = listener.accept().unwrap();
    stream.set_nonblocking(true).unwrap();
    listener.set_nonblocking(true).unwrap();
    let worker = Worker::new(listener, relay.clone()).unwrap();
    let socket = Socket::new(
        mio::net::TcpStream::from_std(stream),
        Token(2),
        worker.registry.clone(),
        worker.signal.clone(),
        &relay,
    )
    .unwrap();
    relay.metrics.connections.fetch_add(1, Relaxed);
    let mut connection = Connection::new(
        socket.clone(),
        Token(2),
        None,
        ConnectionGuard(relay.metrics.clone()),
        &relay,
    );
    let registration = relay
        .subscribe_with_output(b"retained", socket.clone())
        .unwrap();
    let retained = registration.peer.clone();
    connection.registration = Some(registration);
    let mut client = WebSocket::from_raw_socket(client, Role::Client, None);
    assert!(matches!(client.read().unwrap(), Message::Binary(_)));
    drop(socket);
    drop(connection);
    assert_eq!(relay.counts(), (0, 1));
    assert_eq!(
        relay.metrics.connections.load(Relaxed),
        1,
        "retiring membership cannot release capacity while a captured target owns TCP"
    );
    client.get_mut().set_nonblocking(true).unwrap();
    let mut byte = [0];
    assert_eq!(
        client.get_mut().read(&mut byte).unwrap_err().kind(),
        io::ErrorKind::WouldBlock
    );
    drop(retained);
    assert_eq!(relay.metrics.connections.load(Relaxed), 0);
    client.get_mut().set_nonblocking(false).unwrap();
    assert_eq!(client.get_mut().read(&mut byte).unwrap(), 0);
    assert_eq!(relay.metrics.queued_bytes.load(Relaxed), 0);
}

prototype_server_source:
//! Native readiness-driven relay. One event loop owns each decoder; socket
//! output is serialized and can be submitted directly by any routing worker.
//! Idle connections need no task, message channel, or receive allocation.
mod socket;
mod timers;

#[cfg(all(test, target_os = "linux"))]
mod close_tests;
#[cfg(test)]
mod ownership_tests;

pub use crate::admin::admin_router;

use std::{
    collections::{HashMap, VecDeque},
    io::{self, Write},
    num::NonZeroUsize,
    sync::{
        Arc,
        atomic::{
            AtomicBool,
            Ordering::{Acquire, Relaxed},
        },
    },
    time::{Duration, Instant},
};

use anyhow::{Context, Result};
use bytes::Bytes;
use mio::{Events, Interest, Poll, Registry, Token, net::TcpListener};
use slab::Slab;
use tokio::{net::TcpListener as AsyncListener, task::JoinSet};
use tokio_tungstenite::tungstenite::{
    self, Error, Message, WebSocket,
    handshake::{
        HandshakeError, MidHandshake,
        server::{Callback, ErrorResponse, Request, Response, ServerHandshake},
    },
    protocol::{CloseFrame, ReadLease, ReadStorage, WebSocketConfig, frame::coding::CloseCode},
};
use tokio_util::sync::CancellationToken;

use crate::{
    Relay,
    protocol::{self, Disconnect},
    relay::Registration,
};
use socket::{Signal, Socket, Stream};
use timers::Timers;

const LISTENER: Token = Token(0);
const WAKE: Token = Token(1);
const READ_QUANTUM: usize = 256;
const ACCEPT_QUANTUM: usize = 64;

/// Run pre-bound listeners. Tokio services management and signals; native data
/// sockets belong to a fixed number of readiness workers.
pub async fn serve(
    listener: AsyncListener,
    admin: Option<AsyncListener>,
    relay: Arc<Relay>,
    shutdown: CancellationToken,
) -> Result<()> {
    let listener = listener.into_std()?;
    let workers = relay.config.workers.unwrap_or_else(|| {
        std::thread::available_parallelism()
            .map_or(2, usize::from)
            .min(16)
    });
    let mut prepared = Vec::with_capacity(workers);
    for listener in worker_listeners(listener, workers)? {
        prepared.push(Worker::new(listener, relay.clone())?);
    }
    let signals = StopOnDrop {
        signals: prepared
            .iter()
            .map(|worker| worker.signal.clone())
            .collect(),
        relay: relay.clone(),
    };
    let mut tasks = JoinSet::new();
    for (index, worker) in prepared.into_iter().enumerate() {
        let (finished, result) = tokio::sync::oneshot::channel();
        // These loops own dedicated OS threads. An embedder's Tokio blocking
        // pool may be small or busy and must not limit native I/O concurrency.
        let thread = std::thread::Builder::new()
            .name(format!("war-io-{index}"))
            .spawn(move || {
                let outcome = worker.run();
                let _ = finished.send(outcome);
            })
            .context("cannot start native I/O worker")?;
        tasks.spawn(async move {
            let outcome = result.await;
            thread
                .join()
                .map_err(|_| anyhow::anyhow!("native I/O worker panicked"))?;
            outcome.context("native I/O worker stopped without reporting")?
        });
    }
    let admin_stop = CancellationToken::new();
    if let Some(admin) = admin {
        let stop = admin_stop.clone();
        let router = admin_router(relay.clone());
        tasks.spawn(async move {
            axum::serve(admin, router)
                .with_graceful_shutdown(stop.cancelled_owned())
                .await
                .context("admin listener failed")
        });
    }
    let result = tokio::select! {
        _ = shutdown.cancelled() => Ok(()),
        result = tasks.join_next() => match result {
            Some(Ok(Err(error))) => Err(error),
            Some(Err(error)) => Err(error.into()),
            _ => Err(anyhow::anyhow!("service worker stopped unexpectedly")),
        },
    };
    relay.begin_shutdown();
    for signal in &signals.signals {
        signal.stop();
    }
    admin_stop.cancel();
    shutdown.cancel();
    let deadline = Duration::from_secs(relay.config.shutdown_timeout_secs);
    let cleanup = async {
        while let Some(worker) = tasks.join_next().await {
            worker.context("service worker panicked")??;
        }
        Ok::<_, anyhow::Error>(())
    };
    // Workers have their own bounded shutdown deadline. Give cleanup one extra
    // second to return those results rather than detaching an active data loop.
    tokio::time::timeout(deadline + Duration::from_secs(1), cleanup)
        .await
        .context("service shutdown exceeded its deadline")??;
    result
}

fn worker_listeners(
    listener: std::net::TcpListener,
    workers: usize,
) -> io::Result<Vec<std::net::TcpListener>> {
    let mut listeners = Vec::with_capacity(workers);
    // Linux distributes new flows across independent accept queues. Cloning one
    // listen socket lets a single ready worker consume all arrivals instead.
    #[cfg(target_os = "linux")]
    {
        let address = listener.local_addr()?;
        let original = socket2::SockRef::from(&listener);
        original.set_reuse_port(true)?;
        let only_v6 = address.is_ipv6().then(|| original.only_v6()).transpose()?;
        for _ in 1..workers {
            let socket = socket2::Socket::new(
                socket2::Domain::for_address(address),
                socket2::Type::STREAM,
                Some(socket2::Protocol::TCP),
            )?;
            socket.set_reuse_address(true)?;
            socket.set_reuse_port(true)?;
            if let Some(only_v6) = only_v6 {
                socket.set_only_v6(only_v6)?;
            }
            socket.set_nonblocking(true)?;
            socket.bind(&address.into())?;
            socket.listen(1024)?;
            listeners.push(socket.into());
        }
    }
    #[cfg(not(target_os = "linux"))]
    for _ in 1..workers {
        listeners.push(listener.try_clone()?);
    }
    listeners.push(listener);
    Ok(listeners)
}

struct StopOnDrop {
    signals: Vec<Arc<Signal>>,
    relay: Arc<Relay>,
}
impl Drop for StopOnDrop {
    fn drop(&mut self) {
        // Also covers cancellation of the embedding serve future. Publish
        // notification suppression before any worker observes the stop signal.
        self.relay.begin_shutdown();
        for signal in &self.signals {
            signal.stop();
        }
    }
}

struct Worker {
    poll: Poll,
    registry: Arc<Registry>,
    listener: TcpListener,
    signal: Arc<Signal>,
    relay: Arc<Relay>,
    connections: Slab<Connection>,
    tokens: HashMap<Token, usize>,
    next_token: usize,
    ready: VecDeque<Token>,
    timers: Timers,
    scratch: ReadStorage,
}

impl Drop for Worker {
    fn drop(&mut self) {
        // A fatal poll/accept error or panic also retires membership. Suppress
        // fanout before fields drop, even before the supervisor sees the error.
        self.relay.begin_shutdown();
    }
}

impl Worker {
    fn new(listener: std::net::TcpListener, relay: Arc<Relay>) -> io::Result<Self> {
        let poll = Poll::new()?;
        let registry = Arc::new(poll.registry().try_clone()?);
        let mut listener = TcpListener::from_std(listener);
        registry.register(&mut listener, LISTENER, Interest::READABLE)?;
        let signal = Arc::new(Signal {
            waker: mio::Waker::new(&registry, WAKE)?,
            stopping: AtomicBool::new(false),
            pending: parking_lot::Mutex::new(VecDeque::new()),
        });
        Ok(Self {
            poll,
            registry,
            listener,
            signal,
            relay,
            connections: Slab::new(),
            tokens: HashMap::new(),
            next_token: 2,
            ready: VecDeque::new(),
            timers: Timers::default(),
            scratch: ReadStorage::default(),
        })
    }

    fn schedule(&mut self, token: Token) {
        let Some(&slot) = self.tokens.get(&token) else {
            return;
        };
        if let Some(connection) = self.connections.get_mut(slot)
            && connection.token == token
            && !connection.scheduled
        {
            connection.scheduled = true;
            self.ready.push_back(token);
        }
    }

    fn accept(&mut self) -> io::Result<()> {
        for _ in 0..ACCEPT_QUANTUM {
            let (mut stream, _) = match self.listener.accept() {
                Err(error) if error.kind() == io::ErrorKind::WouldBlock => return Ok(()),
                Err(error) if error.kind() == io::ErrorKind::Interrupted => continue,
                accepted => accepted?,
            };
            let metrics = &self.relay.metrics;
            metrics.accepted.fetch_add(1, Relaxed);
            if self.relay.draining.load(Relaxed)
                || metrics
                    .connections
                    .fetch_update(Relaxed, Relaxed, |count| {
                        (count < self.relay.config.max_connections).then_some(count + 1)
                    })
                    .is_err()
            {
                metrics.rejected.fetch_add(1, Relaxed);
                continue;
            }
            let guard = ConnectionGuard(metrics.clone());
            stream.set_nodelay(true)?;
            let lease = match &metrics.read_budget {
                Some(budget) => {
                    match budget.try_lease(self.relay.config.handshake_read_reservation()) {
                        Ok(lease) => Some(lease),
                        Err(_) => {
                            metrics.rejected.fetch_add(1, Relaxed);
                            let _ = stream.write_all(b"HTTP/1.1 503 Service Unavailable\r\nConnection: close\r\nContent-Length: 0\r\n\r\n");
                            continue;
                        }
                    }
                }
                None => None,
            };
            // Tokens never repeat, even when slab slots are reused. Use the
            // full pointer width rather than spending half on a slot index:
            // on 64-bit hosts, heavy churn cannot exhaust a 32-bit generation.
            let token = Token(self.next_token);
            self.next_token = self
                .next_token
                .checked_add(1)
                .ok_or_else(|| io::Error::other("connection token space exhausted"))?;
            let slot = self.connections.vacant_key();
            let socket = Socket::new(
                stream,
                token,
                self.registry.clone(),
                self.signal.clone(),
                &self.relay,
            )?;
            let connection = Connection::new(socket, token, lease, guard, &self.relay);
            let deadline = connection.deadline(&self.relay);
            self.connections.insert(connection);
            self.tokens.insert(token, slot);
            self.timers.set(slot, deadline);
            self.schedule(token);
        }
        // EPOLLET requires an explicit continuation when we yield before
        // WouldBlock. The listener uses the same bounded ready queue.
        self.ready.push_back(LISTENER);
        Ok(())
    }

    fn run(mut self) -> Result<()> {
        let mut events = Events::with_capacity(1024);
        let mut shutdown_deadline = None;
        loop {
            if self.signal.stopping.load(Acquire) && shutdown_deadline.is_none() {
                self.registry.deregister(&mut self.listener)?;
                shutdown_deadline = Some(
                    Instant::now() + Duration::from_secs(self.relay.config.shutdown_timeout_secs),
                );
                for (_, connection) in self.connections.iter_mut() {
                    if !connection.scheduled {
                        connection.scheduled = true;
                        self.ready.push_back(connection.token);
                    }
                }
            }
            if shutdown_deadline.is_some_and(|d| d <= Instant::now())
                || (shutdown_deadline.is_some() && self.connections.is_empty())
            {
                break;
            }
            let now = Instant::now();
            while let Some(slot) = self.timers.pop_due(now) {
                if let Some(connection) = self.connections.get(slot) {
                    self.schedule(connection.token);
                }
            }
            // A bounded ready batch makes progress on buffered continuations
            // without starving new socket events, timers, or shutdown signals.
            let batch = self.ready.len().min(1024);
            for _ in 0..batch {
                let token = self.ready.pop_front().expect("ready batch");
                if token == LISTENER {
                    if shutdown_deadline.is_none() {
                        self.accept()?;
                    }
                    continue;
                }
                let Some(&slot) = self.tokens.get(&token) else {
                    continue;
                };
                let Some(connection) = self.connections.get_mut(slot).filter(|c| c.token == token)
                else {
                    continue;
                };
                connection.scheduled = false;
                connection.socket.notified();
                let keep =
                    connection.drive(&self.relay, &mut self.scratch, shutdown_deadline.is_some());
                match keep {
                    Drive::Drop => {
                        self.timers.remove(slot);
                        self.connections.remove(slot);
                        self.tokens.remove(&token);
                        if self.tokens.capacity() > 256
                            && self.tokens.len() <= self.tokens.capacity() / 8
                        {
                            self.tokens.shrink_to(self.tokens.len() * 2);
                        }
                        if self.connections.is_empty() {
                            self.scratch = ReadStorage::default();
                            // Retain small arenas for churn. A large population
                            // wave must not leave megabytes of empty connection
                            // records and timer indices on an idle worker.
                            if self.connections.capacity() > 256 {
                                self.connections = Slab::new();
                                self.tokens = HashMap::new();
                                self.timers = Timers::default();
                            }
                        }
                    }
                    Drive::Wait | Drive::Again => {
                        let deadline = self.connections[slot].deadline(&self.relay);
                        self.timers.set(slot, deadline);
                        if keep == Drive::Again {
                            self.schedule(token);
                        }
                    }
                }
            }
            {
                let mut pending = self.signal.pending.lock();
                while let Some(token) = pending.pop_front() {
                    let Some(&slot) = self.tokens.get(&token) else {
                        continue;
                    };
                    if let Some(connection) = self.connections.get_mut(slot)
                        && connection.token == token
                        && !connection.scheduled
                    {
                        connection.scheduled = true;
                        self.ready.push_back(token);
                    }
                }
            }
            if shutdown_deadline.is_some() && self.connections.is_empty() {
                break;
            }
            let now = Instant::now();
            let mut timeout = self.timers.next().map(|d| d.saturating_duration_since(now));
            if let Some(deadline) = shutdown_deadline {
                timeout = Some(
                    timeout.map_or(deadline.saturating_duration_since(now), |t| {
                        t.min(deadline.saturating_duration_since(now))
                    }),
                );
            }
            if !self.ready.is_empty() {
                timeout = Some(Duration::ZERO);
            }
            match self.poll.poll(&mut events, timeout) {
                Err(error) if error.kind() == io::ErrorKind::Interrupted => continue,
                result => result?,
            }
            for event in &events {
                match event.token() {
                    LISTENER if shutdown_deadline.is_none() => self.accept()?,
                    LISTENER | WAKE => {}
                    token => self.schedule(token),
                }
            }
        }
        Ok(())
    }
}

struct ConnectionGuard(Arc<crate::metrics::Metrics>);
impl Drop for ConnectionGuard {
    fn drop(&mut self) {
        self.0.connections.fetch_sub(1, Relaxed);
    }
}

struct UpgradePolicy(Arc<Relay>);
impl Callback for UpgradePolicy {
    fn on_request(
        self,
        request: &Request,
        mut response: Response,
    ) -> std::result::Result<Response, ErrorResponse> {
        if !self.0.config.origin_policy.allows(request.headers()) {
            self.0.metrics.rejected.fetch_add(1, Relaxed);
            self.0.metrics.origin_rejected.fetch_add(1, Relaxed);
            return Err(crate::origin::forbidden());
        }
        if let Some(protocols) = request.headers().get("sec-websocket-protocol") {
            if protocols
                .to_str()
                .ok()
                .is_some_and(|s| s.split(',').any(|s| s.trim() == protocol::SUBPROTOCOL))
            {
                response.headers_mut().insert(
                    "sec-websocket-protocol",
                    protocol::SUBPROTOCOL.parse().expect("static header"),
                );
            } else {
                return Err(tungstenite::http::Response::builder()
                    .status(400)
                    .body(Some("Unsupported subprotocol".into()))
                    .expect("static response"));
            }
        }
        Ok(response)
    }
}

type Upgrade = MidHandshake<ServerHandshake<Stream, UpgradePolicy>>;
// The live decoder stays inline in the connection slab. Boxing the steady
// state to match the temporary handshake variant would add an idle allocation.
#[allow(clippy::large_enum_variant)]
enum Stage {
    Upgrade(Option<Box<Upgrade>>),
    WebSocket(WebSocket<Stream>),
}

struct Connection {
    token: Token,
    scheduled: bool,
    socket: Arc<Socket>,
    stage: Stage,
    handshake_lease: Option<ReadLease>,
    registration: Option<Registration>,
    phase_deadline: Instant,
    closing: Option<Closing>,
    limiter: RateLimiter,
    next_ping: Instant,
    pong_deadline: Option<Instant>,
    reclaim_deadline: Option<Instant>,
    _guard: ConnectionGuard,
}

struct Closing {
    deadline: Instant,
    flush_only: bool,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Drive {
    Drop,
    Wait,
    Again,
}

impl Connection {
    fn new(
        socket: Arc<Socket>,
        token: Token,
        lease: Option<ReadLease>,
        guard: ConnectionGuard,
        relay: &Arc<Relay>,
    ) -> Self {
        let config = &relay.config;
        let ws_config = WebSocketConfig::default()
            .read_buffer_size(config.read_buffer_bytes)
            .shared_read_buffer(true)
            .write_buffer_size(4096)
            .max_write_buffer_size(config.queue_bytes + 4096)
            .max_message_size(Some(config.max_message_bytes))
            .max_frame_size(Some(config.max_message_bytes.max(125)));
        let handshake = ServerHandshake::start(
            Stream {
                socket: socket.clone(),
                remaining_upgrade: Some(crate::config::MAX_HTTP_UPGRADE_BYTES),
            },
            UpgradePolicy(relay.clone()),
            Some(ws_config),
        );
        let now = Instant::now();
        Self {
            token,
            scheduled: false,
            socket,
            stage: Stage::Upgrade(Some(Box::new(handshake))),
            handshake_lease: lease,
            registration: None,
            phase_deadline: now + Duration::from_secs(config.handshake_timeout_secs),
            closing: None,
            limiter: RateLimiter::new(config.messages_per_second, config.bytes_per_second, now),
            next_ping: now + Duration::from_secs(config.ping_interval_secs.max(1)),
            pong_deadline: None,
            reclaim_deadline: None,
            _guard: guard,
        }
    }

    fn deadline(&self, relay: &Relay) -> Option<Instant> {
        if let Some(closing) = &self.closing {
            return Some(closing.deadline);
        }
        if matches!(self.stage, Stage::Upgrade(_)) || self.registration.is_none() {
            return Some(self.phase_deadline);
        }
        let mut deadline = self.socket.deadline();
        for next in [
            self.pong_deadline,
            self.reclaim_deadline,
            (relay.config.ping_interval_secs > 0).then_some(self.next_ping),
        ]
        .into_iter()
        .flatten()
        {
            deadline = Some(deadline.map_or(next, |d| d.min(next)));
        }
        if relay.config.idle_timeout_secs > 0 {
            let next = self.socket.state.lock().activity
                + Duration::from_secs(relay.config.idle_timeout_secs);
            deadline = Some(deadline.map_or(next, |d| d.min(next)));
        }
        deadline
    }

    fn drive(&mut self, relay: &Arc<Relay>, scratch: &mut ReadStorage, stopping: bool) -> Drive {
        let now = Instant::now();
        if let Stage::Upgrade(handshake) = &mut self.stage {
            if stopping {
                return Drive::Drop;
            }
            if now >= self.phase_deadline {
                relay.metrics.handshake_errors.fetch_add(1, Relaxed);
                return Drive::Drop;
            }
            match handshake.take().expect("pending handshake").handshake() {
                Ok(mut ws) => {
                    ws.get_mut().remaining_upgrade = None;
                    if let Some(lease) = self.handshake_lease.take()
                        && ws.set_read_budget(lease).is_err()
                    {
                        return Drive::Drop;
                    }
                    if self.socket.control_flushed().is_err() {
                        return Drive::Drop;
                    }
                    self.phase_deadline = now + Duration::from_secs(relay.config.join_timeout_secs);
                    self.stage = Stage::WebSocket(ws);
                }
                Err(HandshakeError::Interrupted(mid)) => {
                    *handshake = Some(Box::new(mid));
                    return Drive::Wait;
                }
                Err(HandshakeError::Failure(Error::Http(response))) if response.status() == 403 => {
                    return Drive::Drop;
                }
                Err(_) => {
                    relay.metrics.handshake_errors.fetch_add(1, Relaxed);
                    return Drive::Drop;
                }
            }
        }
        let Stage::WebSocket(ws) = &mut self.stage else {
            unreachable!()
        };
        ws.swap_read_storage(scratch);
        let result = self.drive_websocket(relay, now, stopping);
        let Stage::WebSocket(ws) = &mut self.stage else {
            unreachable!()
        };
        if let Some(mut storage) = ws.take_read_storage() {
            // A small message on another connection must not inherit and pin a
            // previous large receive slab. Refill lazily on the next read.
            storage.discard_if_larger_than(relay.config.read_buffer_bytes.max(14));
            *scratch = storage;
        }
        result
    }

    fn start_close(
        &mut self,
        reason: Disconnect,
        relay: &Relay,
        acknowledge: bool,
        now: Instant,
    ) -> Drive {
        if self.closing.is_some() {
            return Drive::Wait;
        }
        if reason.code == 1002 && self.registration.is_some() {
            relay.metrics.protocol_errors.fetch_add(1, Relaxed);
        }
        if reason == Disconnect::RATE {
            relay.metrics.rate_limited.fetch_add(1, Relaxed);
        }
        if self.registration.is_none() && !acknowledge && reason != Disconnect::SHUTDOWN {
            relay.metrics.join_rejected.fetch_add(1, Relaxed);
        }
        // Remove membership before waiting on a peer's Close acknowledgement.
        self.registration.take();
        if self.socket.end_output() {
            return Drive::Drop;
        }
        let Stage::WebSocket(ws) = &mut self.stage else {
            return Drive::Drop;
        };
        self.closing = Some(Closing {
            deadline: now + relay.config.write_timeout(),
            flush_only: acknowledge,
        });
        if acknowledge {
            return self.finish_peer_close(relay);
        }
        match ws.close(Some(CloseFrame {
            code: CloseCode::from(reason.code),
            reason: reason.reason.into(),
        })) {
            Ok(()) => {}
            Err(Error::Io(error)) if error.kind() == io::ErrorKind::WouldBlock => {}
            Err(error) => {
                tracing::debug!(token = self.token.0, %error, "Close send failed");
                relay.metrics.close_failures.fetch_add(1, Relaxed);
                return Drive::Drop;
            }
        }
        Drive::Again
    }

    /// A received Close completes the exchange once queued control bytes reach
    /// TCP. Flush in this turn; only actual backpressure needs another event.
    fn finish_peer_close(&mut self, relay: &Relay) -> Drive {
        self.closing.as_mut().expect("closing exchange").flush_only = true;
        let Stage::WebSocket(ws) = &mut self.stage else {
            unreachable!()
        };
        match ws.flush() {
            Ok(()) | Err(Error::ConnectionClosed | Error::AlreadyClosed) => Drive::Drop,
            Err(Error::Io(error)) if error.kind() == io::ErrorKind::WouldBlock => Drive::Wait,
            Err(error) => {
                tracing::debug!(token = self.token.0, %error, "Close acknowledgement flush failed");
                relay.metrics.close_failures.fetch_add(1, Relaxed);
                Drive::Drop
            }
        }
    }

    fn drive_websocket(&mut self, relay: &Arc<Relay>, now: Instant, stopping: bool) -> Drive {
        let (fatal, requested) = {
            let state = self.socket.state.lock();
            (state.fatal, state.requested)
        };
        if fatal {
            return Drive::Drop;
        }
        if self.closing.is_none() {
            if let Some(reason) = requested.or(stopping.then_some(Disconnect::SHUTDOWN)) {
                // A notification burst may fill an untouched queue while the
                // peer's Close is already readable. Preserve that handshake
                // before starting a competing overload Close. Partial output
                // still forces TCP retirement in start_close.
                if reason == Disconnect::OVERLOADED {
                    let Stage::WebSocket(ws) = &mut self.stage else {
                        unreachable!()
                    };
                    if matches!(
                        ws.read_with_frame_limit(
                            NonZeroUsize::new(READ_QUANTUM).expect("read quantum")
                        ),
                        Ok(Some(Message::Close(_)))
                    ) {
                        return self.start_close(
                            Disconnect {
                                code: 1000,
                                reason: "",
                            },
                            relay,
                            true,
                            now,
                        );
                    }
                }
                return self.start_close(reason, relay, false, now);
            }
            if self.socket.deadline().is_some_and(|d| d <= now) {
                relay.metrics.write_timeouts.fetch_add(1, Relaxed);
                return Drive::Drop;
            }
            if self.registration.is_none() && now >= self.phase_deadline {
                return self.start_close(
                    Disconnect {
                        code: 1008,
                        reason: "Channel Join Timeout",
                    },
                    relay,
                    false,
                    now,
                );
            }
            if self.pong_deadline.is_some_and(|d| d <= now) {
                return self.start_close(
                    Disconnect {
                        code: 1001,
                        reason: "Heartbeat Timeout",
                    },
                    relay,
                    false,
                    now,
                );
            }
            if self.registration.is_some() && relay.config.idle_timeout_secs > 0 {
                let output_pending = self.socket.deadline().is_some();
                let mut state = self.socket.state.lock();
                if state.activity + Duration::from_secs(relay.config.idle_timeout_secs) <= now {
                    if !output_pending {
                        drop(state);
                        relay.metrics.idle_timeouts.fetch_add(1, Relaxed);
                        return self.start_close(Disconnect::IDLE, relay, false, now);
                    }
                    state.activity = now;
                }
            }
        }
        let mut again = match self.socket.flush() {
            Ok(again) => again,
            Err(_) => {
                relay.metrics.write_errors.fetch_add(1, Relaxed);
                return Drive::Drop;
            }
        };
        let Stage::WebSocket(ws) = &mut self.stage else {
            unreachable!()
        };
        match ws.flush() {
            Ok(()) => {
                if self.socket.control_flushed().is_err() {
                    return Drive::Drop;
                }
            }
            Err(Error::Io(error)) if error.kind() == io::ErrorKind::WouldBlock => {}
            Err(Error::ConnectionClosed | Error::AlreadyClosed) => return Drive::Drop,
            Err(error) => {
                tracing::debug!(token = self.token.0, %error, closing = self.closing.is_some(), "control flush failed");
                relay.metrics.close_failures.fetch_add(1, Relaxed);
                return Drive::Drop;
            }
        }
        if let Some(closing) = &self.closing {
            if closing.deadline <= now {
                tracing::debug!(
                    token = self.token.0,
                    "Close acknowledgement deadline expired"
                );
                relay.metrics.close_failures.fetch_add(1, Relaxed);
                return Drive::Drop;
            }
            if closing.flush_only || stopping {
                // The peer's Close is already consumed. Reading this closed
                // decoder can terminate it while its reply is still buffered.
                // Only writable readiness or the Close deadline may finish it.
                return if self.socket.state.lock().control_pending {
                    Drive::Wait
                } else {
                    Drive::Drop
                };
            }
        }
        if self.closing.is_none()
            && self.registration.is_some()
            && relay.config.ping_interval_secs > 0
            && self.next_ping <= now
        {
            self.next_ping = now + Duration::from_secs(relay.config.ping_interval_secs);
            if self.pong_deadline.is_none() {
                match ws.send(Message::Ping(Bytes::from_static(b"war"))) {
                    Ok(()) => {
                        if self.socket.control_flushed().is_err() {
                            return Drive::Drop;
                        }
                    }
                    Err(Error::Io(error)) if error.kind() == io::ErrorKind::WouldBlock => {}
                    Err(_) => {
                        relay.metrics.write_errors.fetch_add(1, Relaxed);
                        return Drive::Drop;
                    }
                }
                self.pong_deadline =
                    Some(now + Duration::from_secs(relay.config.pong_timeout_secs));
            }
        }
        if self.reclaim_deadline.is_some_and(|d| d <= now) {
            if let Some(copied) = ws.reclaim_read_buffer() {
                relay.metrics.read_buffer_reclaims.fetch_add(1, Relaxed);
                relay
                    .metrics
                    .read_buffer_reclaim_header_bytes
                    .fetch_add(copied as u64, Relaxed);
                self.reclaim_deadline = None;
            } else {
                relay
                    .metrics
                    .read_buffer_reclaims_deferred
                    .fetch_add(1, Relaxed);
                self.reclaim_deadline =
                    Some(now + Duration::from_secs(relay.config.read_buffer_idle_secs));
            }
        }
        for _ in 0..READ_QUANTUM {
            let Stage::WebSocket(ws) = &mut self.stage else {
                unreachable!()
            };
            match ws.read_with_frame_limit(NonZeroUsize::new(1).expect("one frame")) {
                Ok(None) => continue,
                Ok(Some(Message::Close(_))) => {
                    if self.closing.is_some() {
                        return self.finish_peer_close(relay);
                    }
                    return self.start_close(
                        Disconnect {
                            code: 1000,
                            reason: "",
                        },
                        relay,
                        true,
                        now,
                    );
                }
                Ok(Some(_)) if self.closing.is_some() => continue,
                Ok(Some(message)) => {
                    if !self.limiter.allow(message.len(), now) {
                        return self.start_close(Disconnect::RATE, relay, false, now);
                    }
                    match message {
                        Message::Binary(bytes) => {
                            if let Some(registration) = &self.registration {
                                let large = relay.config.read_buffer_idle_secs > 0
                                    && bytes.len() > relay.config.read_buffer_bytes.max(64 * 1024);
                                let capacity = ws.read_storage_capacity().max(bytes.len());
                                if let Err(reason) =
                                    relay.receive_with_storage(&registration.peer, bytes, capacity)
                                {
                                    return self.start_close(reason, relay, false, now);
                                }
                                if large {
                                    self.reclaim_deadline = Some(
                                        now + Duration::from_secs(
                                            relay.config.read_buffer_idle_secs,
                                        ),
                                    );
                                }
                            } else {
                                let registration = protocol::join(&bytes).and_then(|channel| {
                                    relay.subscribe_with_output(channel, self.socket.clone())
                                });
                                match registration {
                                    Ok(registration) => {
                                        self.registration = Some(registration);
                                        self.next_ping = now
                                            + Duration::from_secs(
                                                relay.config.ping_interval_secs.max(1),
                                            );
                                    }
                                    Err(reason) => {
                                        return self.start_close(reason, relay, false, now);
                                    }
                                }
                            }
                            if relay.config.idle_timeout_secs > 0 {
                                self.socket.state.lock().activity = Instant::now();
                            }
                        }
                        Message::Ping(_) => match ws.flush() {
                            Ok(()) => {
                                if self.socket.control_flushed().is_err() {
                                    return Drive::Drop;
                                }
                            }
                            Err(Error::Io(error)) if error.kind() == io::ErrorKind::WouldBlock => {}
                            Err(_) => {
                                relay.metrics.write_errors.fetch_add(1, Relaxed);
                                return Drive::Drop;
                            }
                        },
                        Message::Pong(bytes) => {
                            if bytes.as_ref() == b"war" {
                                self.pong_deadline = None;
                            }
                        }
                        _ => {
                            return self.start_close(
                                Disconnect {
                                    code: 1003,
                                    reason: "CBOR Binary Messages Required",
                                },
                                relay,
                                false,
                                now,
                            );
                        }
                    }
                }
                Err(Error::Io(error)) if error.kind() == io::ErrorKind::WouldBlock => {
                    match self.socket.flush() {
                        Ok(ready) => again |= ready,
                        Err(_) => {
                            relay.metrics.write_errors.fetch_add(1, Relaxed);
                            return Drive::Drop;
                        }
                    }
                    return if again { Drive::Again } else { Drive::Wait };
                }
                Err(Error::ConnectionClosed | Error::AlreadyClosed) => return Drive::Drop,
                Err(
                    Error::Io(_)
                    | Error::Protocol(
                        tungstenite::error::ProtocolError::ResetWithoutClosingHandshake,
                    ),
                ) => {
                    if self.registration.is_some() {
                        relay.metrics.transport_disconnects.fetch_add(1, Relaxed);
                    }
                    return Drive::Drop;
                }
                Err(error) => {
                    let reason = match error {
                        Error::Capacity(
                            tungstenite::error::CapacityError::ReadBufferBudgetExceeded,
                        ) => Disconnect {
                            code: 1013,
                            reason: "Input Memory Limit",
                        },
                        Error::Capacity(_) => Disconnect {
                            code: 1009,
                            reason: "Message Too Large",
                        },
                        _ => Disconnect::PROTOCOL,
                    };
                    let result = self.start_close(reason, relay, false, now);
                    // A framing/decoder rejection has no trustworthy input
                    // continuation. Flush its best-effort Close, then retire;
                    // do not reinterpret an acknowledgement as the denied body.
                    if let Some(closing) = &mut self.closing {
                        closing.flush_only = true;
                    }
                    return result;
                }
            }
        }
        Drive::Again
    }
}

impl Drop for Connection {
    fn drop(&mut self) {
        // This may be the last strong peer/socket reference. Disable output
        // before retiring membership and releasing queued byte reservations.
        self.socket.end_output();
        self.registration.take();
    }
}

struct RateLimiter {
    rates: [u64; 2],
    tokens: [f64; 2],
    updated: Instant,
}
impl RateLimiter {
    fn new(messages: u64, bytes: u64, now: Instant) -> Self {
        Self {
            rates: [messages, bytes],
            tokens: [messages as f64, bytes as f64],
            updated: now,
        }
    }
    fn allow(&mut self, bytes: usize, now: Instant) -> bool {
        if self.rates == [0, 0] {
            return true;
        }
        let elapsed = now.duration_since(self.updated).as_secs_f64();
        self.updated = now;
        for (i, cost) in [1.0, bytes as f64].into_iter().enumerate() {
            let rate = self.rates[i] as f64;
            if rate == 0.0 {
                continue;
            }
            self.tokens[i] = (self.tokens[i] + elapsed * rate).min(rate);
            if self.tokens[i] < cost {
                return false;
            }
            self.tokens[i] -= cost;
        }
        true
    }
}

#[cfg(all(test, target_os = "linux"))]
mod tests {
    use super::*;

    #[test]
    fn worker_listeners_keep_an_embedders_ipv6_only_boundary() {
        let ipv4 = std::net::TcpListener::bind("0.0.0.0:0").unwrap();
        let port = ipv4.local_addr().unwrap().port();
        let original = socket2::Socket::new(
            socket2::Domain::IPV6,
            socket2::Type::STREAM,
            Some(socket2::Protocol::TCP),
        )
        .unwrap();
        original.set_only_v6(true).unwrap();
        original.set_nonblocking(true).unwrap();
        original
            .bind(&std::net::SocketAddr::from((std::net::Ipv6Addr::UNSPECIFIED, port)).into())
            .unwrap();
        original.listen(128).unwrap();
        let listeners = worker_listeners(original.into(), 4).unwrap();
        assert_eq!(listeners.len(), 4);
        for listener in listeners {
            assert!(socket2::SockRef::from(&listener).only_v6().unwrap());
            assert_eq!(listener.local_addr().unwrap().port(), port);
        }
    }
}

prototype_socket_source:
//! Socket output has one serialized owner at a time, including writes from a
//! different relay worker. The ordinary path writes borrowed slices immediately.
//! Only backpressure allocates queue storage or retains a message body.
use std::{
    collections::VecDeque,
    io::{self, IoSlice, Read, Write},
    sync::{
        Arc,
        atomic::{
            AtomicBool,
            Ordering::{Relaxed, Release},
        },
    },
    time::{Duration, Instant},
};

use mio::{Interest, Registry, Token, Waker, net::TcpStream};
use parking_lot::Mutex;

use crate::{
    frame::Frame,
    metrics::Metrics,
    protocol::Disconnect,
    relay::{Envelope, PeerOutput},
};

pub(super) const WRITE_QUANTUM: usize = 256 * 1024;

pub(super) struct Signal {
    pub waker: Waker,
    pub stopping: AtomicBool,
    pub pending: Mutex<VecDeque<Token>>,
}

impl Signal {
    pub fn stop(&self) {
        self.stopping.store(true, Release);
        let _ = self.waker.wake();
    }
}

pub(super) struct Socket {
    pub state: Mutex<State>,
    registry: Arc<Registry>,
    signal: Arc<Signal>,
    pub token: Token,
    notified: AtomicBool,
    metrics: Arc<Metrics>,
    queue_limit: usize,
    write_timeout: Duration,
    track_activity: bool,
}

pub(super) struct State {
    pub stream: TcpStream,
    queue: VecDeque<Pending>,
    pub requested: Option<Disconnect>,
    pub fatal: bool,
    pub closed: bool,
    writable: bool,
    pub control_pending: bool,
    pub control_deadline: Option<Instant>,
    pub activity: Instant,
}

struct Pending {
    packet: Envelope,
    offset: usize,
    deadline: Instant,
}

impl Socket {
    pub fn new(
        stream: TcpStream,
        token: Token,
        registry: Arc<Registry>,
        signal: Arc<Signal>,
        relay: &crate::Relay,
    ) -> io::Result<Arc<Self>> {
        let socket = Arc::new(Self {
            state: Mutex::new(State {
                stream,
                queue: VecDeque::new(),
                requested: None,
                fatal: false,
                closed: false,
                writable: false,
                control_pending: false,
                control_deadline: None,
                activity: Instant::now(),
            }),
            registry,
            signal,
            token,
            notified: AtomicBool::new(false),
            metrics: relay.metrics.clone(),
            queue_limit: relay.config.queue_messages,
            write_timeout: relay.config.write_timeout(),
            track_activity: relay.config.idle_timeout_secs > 0,
        });
        socket
            .registry
            .register(&mut socket.state.lock().stream, token, Interest::READABLE)?;
        Ok(socket)
    }

    fn notify(&self) {
        if !self.notified.swap(true, Relaxed) {
            self.signal.pending.lock().push_back(self.token);
            let _ = self.signal.waker.wake();
        }
    }

    pub fn notified(&self) {
        self.notified.store(false, Relaxed);
    }

    fn writable(&self, state: &mut State, enabled: bool) -> io::Result<()> {
        if state.writable != enabled {
            let interest = if enabled {
                Interest::READABLE | Interest::WRITABLE
            } else {
                Interest::READABLE
            };
            self.registry
                .reregister(&mut state.stream, self.token, interest)?;
            state.writable = enabled;
        }
        Ok(())
    }

    fn delivered(&self, packet: &Envelope, state: &mut State) {
        self.metrics.deliveries.fetch_add(1, Relaxed);
        self.metrics
            .delivered_bytes
            .fetch_add(packet.frame.len() as u64, Relaxed);
        if self.track_activity {
            state.activity = Instant::now();
        }
    }

    pub fn deadline(&self) -> Option<Instant> {
        let state = self.state.lock();
        match (
            state.queue.front().map(|p| p.deadline),
            state.control_deadline,
        ) {
            (Some(a), Some(b)) => Some(a.min(b)),
            (a, b) => a.or(b),
        }
    }

    /// Resume bounded application output. `true` means this socket consumed its
    /// quantum while still ready and must be explicitly scheduled again.
    pub fn flush(&self) -> io::Result<bool> {
        let mut state = self.state.lock();
        if state.control_pending {
            return Ok(false);
        }
        let mut remaining = WRITE_QUANTUM;
        while let Some(mut pending) = state.queue.pop_front() {
            match write_frame(
                &mut state.stream,
                &pending.packet.frame,
                &mut pending.offset,
                remaining,
            ) {
                Ok(written) => {
                    remaining -= written;
                    if pending.offset == wire_len(&pending.packet.frame) {
                        self.delivered(&pending.packet, &mut state);
                    } else {
                        state.queue.push_front(pending);
                    }
                    if remaining == 0 {
                        let queued = !state.queue.is_empty();
                        self.writable(&mut state, queued)?;
                        return Ok(queued);
                    }
                }
                Err(error) if error.kind() == io::ErrorKind::WouldBlock => {
                    state.queue.push_front(pending);
                    self.writable(&mut state, true)?;
                    return Ok(false);
                }
                Err(error) => return Err(error),
            }
        }
        self.writable(&mut state, false)?;
        Ok(false)
    }

    /// Cancel queued application frames before Close. A partially transmitted
    /// frame requires dropping TCP; a Close can never be appended inside it.
    pub fn end_output(&self) -> bool {
        let mut state = self.state.lock();
        state.closed = true;
        let partial = state.queue.front().is_some_and(|p| p.offset != 0);
        if !state.queue.is_empty() {
            self.metrics.aborted_writes.fetch_add(1, Relaxed);
            if !partial {
                self.metrics
                    .unstarted_writes_cancelled
                    .fetch_add(1, Relaxed);
            }
        }
        state.queue.clear();
        partial
    }

    pub fn control_flushed(&self) -> io::Result<()> {
        let mut state = self.state.lock();
        state.control_pending = false;
        state.control_deadline = None;
        let queued = !state.queue.is_empty();
        self.writable(&mut state, queued)
    }
}

impl PeerOutput for Socket {
    fn send(&self, packet: Envelope) -> bool {
        let mut state = self.state.lock();
        if state.closed || state.fatal || state.requested.is_some() {
            return true;
        }
        if state.queue.len() >= self.queue_limit {
            return false;
        }
        let mut offset = 0;
        if state.queue.is_empty() && !state.control_pending {
            match write_frame(&mut state.stream, &packet.frame, &mut offset, WRITE_QUANTUM) {
                Ok(_) if offset == wire_len(&packet.frame) => {
                    self.delivered(&packet, &mut state);
                    return true;
                }
                Ok(_) => {}
                Err(error) if error.kind() == io::ErrorKind::WouldBlock => {}
                Err(_) => {
                    state.fatal = true;
                    self.metrics.write_errors.fetch_add(1, Relaxed);
                    self.notify();
                    return true;
                }
            }
        }
        let first = state.queue.is_empty();
        state.queue.push_back(Pending {
            packet,
            offset,
            deadline: Instant::now() + self.write_timeout,
        });
        if self.writable(&mut state, true).is_err() {
            state.fatal = true;
        }
        if first {
            self.notify();
        }
        true
    }

    fn close(&self, reason: Disconnect) {
        let mut state = self.state.lock();
        if state.closed || state.requested.is_some() {
            return;
        }
        state.requested = Some(reason);
        self.notify();
    }
}

impl Drop for Socket {
    fn drop(&mut self) {
        let _ = self.registry.deregister(&mut self.state.get_mut().stream);
    }
}

/// The codec owns receive/fragment/control state. This small handle serializes
/// its control writes with direct application writes on other workers.
pub(super) struct Stream {
    pub socket: Arc<Socket>,
    pub remaining_upgrade: Option<usize>,
}

impl Read for Stream {
    fn read(&mut self, bytes: &mut [u8]) -> io::Result<usize> {
        let length = match self.remaining_upgrade {
            Some(0) => {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "HTTP upgrade exceeds 16384 bytes",
                ));
            }
            Some(remaining) => remaining.min(bytes.len()),
            None => bytes.len(),
        };
        let read = self.socket.state.lock().stream.read(&mut bytes[..length])?;
        if let Some(remaining) = &mut self.remaining_upgrade {
            *remaining -= read;
        }
        Ok(read)
    }
}

impl Write for Stream {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        let mut state = self.socket.state.lock();
        if state.queue.front().is_some_and(|p| p.offset != 0) {
            return Err(io::ErrorKind::WouldBlock.into());
        }
        state.control_pending = true;
        state
            .control_deadline
            .get_or_insert_with(|| Instant::now() + self.socket.write_timeout);
        match state.stream.write(bytes) {
            Err(error) if error.kind() == io::ErrorKind::WouldBlock => {
                self.socket.writable(&mut state, true)?;
                Err(error)
            }
            result => result,
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

fn header(frame: &Frame, bytes: &mut [u8; 20]) -> usize {
    bytes[0] = 0x82;
    let length = frame.len();
    let size = match length {
        0..=125 => {
            bytes[1] = length as u8;
            2
        }
        126..=65535 => {
            bytes[1] = 126;
            bytes[2..4].copy_from_slice(&(length as u16).to_be_bytes());
            4
        }
        _ => {
            bytes[1] = 127;
            bytes[2..10].copy_from_slice(&(length as u64).to_be_bytes());
            10
        }
    };
    bytes[size..size + frame.prefix().len()].copy_from_slice(frame.prefix());
    size + frame.prefix().len()
}

fn wire_len(frame: &Frame) -> usize {
    frame.len()
        + match frame.len() {
            0..=125 => 2,
            126..=65535 => 4,
            _ => 10,
        }
}

/// The body is never assembled into a new contiguous message. Short writes
/// resume from the header/body offset and retain the original `Bytes` owner.
fn write_frame(
    stream: &mut impl Write,
    frame: &Frame,
    offset: &mut usize,
    quantum: usize,
) -> io::Result<usize> {
    let mut bytes = [0; 20];
    let size = header(frame, &mut bytes);
    let head = &bytes[(*offset).min(size)..size.min(offset.saturating_add(quantum))];
    let body_offset = offset.saturating_sub(size);
    let body = &frame.payload()[body_offset
        ..frame
            .payload()
            .len()
            .min(body_offset + quantum - head.len())];
    let slices = [IoSlice::new(head), IoSlice::new(body)];
    let written = loop {
        match stream.write_vectored(if head.is_empty() {
            &slices[1..]
        } else {
            &slices
        }) {
            Err(error) if error.kind() == io::ErrorKind::Interrupted => continue,
            result => break result?,
        }
    };
    if written == 0 {
        return Err(io::ErrorKind::WriteZero.into());
    }
    *offset += written;
    Ok(written)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{Config, Relay, protocol};
    use mio::Poll;
    use tokio_tungstenite::tungstenite::{Message, WebSocket, protocol::Role};

    struct Probe {
        wire: Vec<u8>,
        pointer: usize,
        borrowed: bool,
        max_write: usize,
        blocked: bool,
    }

    impl Write for Probe {
        fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
            self.write_vectored(&[IoSlice::new(bytes)])
        }
        fn write_vectored(&mut self, slices: &[IoSlice<'_>]) -> io::Result<usize> {
            // Alternate short writes and WouldBlock, including both sides of
            // the header/body boundary. Retrying must not replay any bytes.
            self.blocked = !self.blocked;
            if self.blocked {
                return Err(io::ErrorKind::WouldBlock.into());
            }
            let mut remaining = self.max_write;
            for slice in slices {
                self.borrowed |= slice.as_ptr() as usize == self.pointer;
                let n = remaining.min(slice.len());
                self.wire.extend_from_slice(&slice[..n]);
                remaining -= n;
            }
            Ok(self.max_write - remaining)
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }

    #[test]
    fn direct_vectored_writes_keep_bodies_borrowed_across_short_writes_and_backpressure() {
        for len in [0, 1, 115, 116, 125, 126, 65525, 65526, 65535, 65536, 65537] {
            let input = protocol::envelope(42, &vec![0x5a; len]);
            let packet = Frame::routed(u64::MAX, input, 3, false);
            let mut probe = Probe {
                wire: Vec::new(),
                pointer: packet.payload().as_ptr() as usize,
                borrowed: false,
                max_write: 3,
                blocked: false,
            };
            let mut offset = 0;
            while offset < wire_len(&packet) {
                match write_frame(&mut probe, &packet, &mut offset, 7) {
                    Ok(_) => {}
                    Err(error) if error.kind() == io::ErrorKind::WouldBlock => {}
                    Err(error) => panic!("{error}"),
                }
            }
            assert!(len == 0 || probe.borrowed);
            let mut client =
                WebSocket::from_raw_socket(io::Cursor::new(probe.wire), Role::Client, None);
            assert_eq!(
                client.read().unwrap(),
                Message::Binary(protocol::envelope(u64::MAX, &vec![0x5a; len]))
            );
        }
    }

    #[test]
    fn ordinary_output_has_no_queue_allocation_and_control_never_splits_a_partial_data_frame() {
        let relay = Relay::new(Config {
            ping_interval_secs: 0,
            ..Config::default()
        })
        .unwrap();
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let _reader = std::net::TcpStream::connect(listener.local_addr().unwrap()).unwrap();
        let (stream, _) = listener.accept().unwrap();
        stream.set_nonblocking(true).unwrap();
        let poll = Poll::new().unwrap();
        let registry = Arc::new(poll.registry().try_clone().unwrap());
        let signal = Arc::new(Signal {
            waker: Waker::new(&registry, Token(1)).unwrap(),
            stopping: AtomicBool::new(false),
            pending: Mutex::new(VecDeque::new()),
        });
        let socket = Socket::new(
            TcpStream::from_std(stream),
            Token(2),
            registry,
            signal,
            &relay,
        )
        .unwrap();
        let registration = relay
            .subscribe_with_output(b"test", socket.clone())
            .unwrap();
        let id = registration.peer.id.load(Relaxed);
        relay
            .receive(&registration.peer, protocol::envelope(id, &[0xf6]))
            .unwrap();
        assert_eq!(socket.state.lock().queue.capacity(), 0);
        let body = protocol::byte_string(&vec![0x5a; 1024 * 1024]);
        relay
            .receive(&registration.peer, protocol::envelope(id, &body))
            .unwrap();
        let before = socket.state.lock().queue[0].offset;
        assert!(before > 0 && before <= WRITE_QUANTUM);
        let mut stream = Stream {
            socket: socket.clone(),
            remaining_upgrade: None,
        };
        assert_eq!(
            stream.write(b"control").unwrap_err().kind(),
            io::ErrorKind::WouldBlock
        );
        assert_eq!(socket.state.lock().queue[0].offset, before);
        assert!(relay.metrics.queued_bytes.load(Relaxed) > 0);
        assert!(
            socket.end_output(),
            "a partial frame requires dropping its transport"
        );
        assert_eq!(relay.metrics.queued_bytes.load(Relaxed), 0);
        drop(registration);
        assert_eq!(relay.counts(), (0, 1));
    }
}

prototype_relay_source:
use std::{
    collections::HashMap,
    hash::Hash,
    sync::{
        Arc,
        atomic::{AtomicBool, AtomicU8, AtomicU64, AtomicUsize, Ordering::Relaxed},
    },
};

use anyhow::{Context, Result};
use base64::{Engine, engine::general_purpose::STANDARD};
use bytes::Bytes;
use minicbor::Encoder;
use parking_lot::RwLock;
use serde::Serialize;
#[cfg(test)]
use tokio::sync::{mpsc, watch};

use crate::{
    Config,
    frame::Frame,
    metrics::Metrics,
    protocol::{
        self, BROADCAST, CHANNEL_MESSAGE, Command, DISCONNECT_MESSAGE, Disconnect, GLOBAL_CHANNEL,
        PRIVATE_MESSAGE,
    },
};

/// The registry lock protects membership and ID ownership. Output submission is
/// nonblocking; the transport writes immediately or retains a shared frame.
pub struct Relay {
    pub config: Config,
    pub metrics: Arc<Metrics>,
    pub draining: AtomicBool,
    stopping: AtomicBool,
    state: RwLock<Registry>,
}

struct Registry {
    users: HashMap<u64, Arc<Peer>>,
    channels: HashMap<Bytes, Channel>,
    // Only authenticated global members opting into each class belong here.
    // Routing visits eligible listeners, independent of the idle population.
    listeners: [Vec<Arc<Peer>>; 3],
    next_key: u64,
    sessions: usize,
}

impl Registry {
    fn set_listener_flags(&mut self, peer: &Peer, flags: u8) {
        let previous = peer.listener.load(Relaxed);
        peer.listener.store(flags, Relaxed);
        for (bit, listeners) in self.listeners.iter_mut().enumerate() {
            let mask = 1 << bit;
            if (previous ^ flags) & mask == 0 {
                continue;
            }
            if flags & mask != 0 {
                if let Some(member) = self.channels[GLOBAL_CHANNEL].members.get(&peer.key) {
                    listeners.push(member.clone());
                }
            } else if let Some(position) = listeners.iter().position(|p| p.key == peer.key) {
                listeners.swap_remove(position);
                if listeners.capacity() > 256 && listeners.len() <= listeners.capacity() / 8 {
                    listeners.shrink_to(listeners.len() * 2);
                }
            }
        }
    }

    fn listeners(&self, flag: u8) -> &[Arc<Peer>] {
        &self.listeners[flag.trailing_zeros() as usize]
    }
}

fn shrink_sparse_map<K: Eq + Hash, V>(map: &mut HashMap<K, V>) {
    // HashMap iteration scans spare buckets too. After substantial retirement,
    // release excess slots in ownership, membership and channel-name indexes.
    // Keep small maps and 2x headroom to avoid churn. Rehashing moves metadata;
    // peers, queues, name/variable bytes and shared bodies keep their storage.
    let remaining = map.len();
    let capacity = map.capacity();
    if capacity > 256 && remaining <= capacity / 8 {
        map.shrink_to(remaining * 2);
    }
}

#[derive(Default)]
struct Channel {
    members: HashMap<u64, Arc<Peer>>,
    variables: HashMap<Bytes, Bytes>,
    variable_bytes: usize,
}

pub(crate) struct Peer {
    key: u64,
    pub id: AtomicU64,
    channel: Bytes,
    authenticated: AtomicBool,
    listener: AtomicU8,
    closing: AtomicBool,
    output: Arc<dyn PeerOutput>,
    budget: Arc<Budget>,
}

struct Budget {
    used: AtomicUsize,
    limit: usize,
    global_limit: usize,
    metrics: Arc<Metrics>,
}

/// Byte reservations survive dequeue and remain charged until the actual write
/// completes (or is cancelled). Dropping any queue or failed send releases them.
pub(crate) struct Envelope {
    pub frame: Frame,
    budget: Arc<Budget>,
}

/// A transport owns ordering and backpressure. Sending never waits for socket
/// readiness, and close only signals the owning I/O loop.
pub(crate) trait PeerOutput: Send + Sync {
    fn send(&self, packet: Envelope) -> bool;
    fn close(&self, reason: Disconnect);
}

#[cfg(test)]
struct AsyncOutput {
    outgoing: mpsc::Sender<Envelope>,
    close: watch::Sender<Option<Disconnect>>,
}

#[cfg(test)]
impl PeerOutput for AsyncOutput {
    fn send(&self, packet: Envelope) -> bool {
        self.outgoing.try_send(packet).is_ok()
    }

    fn close(&self, reason: Disconnect) {
        self.close.send_replace(Some(reason));
    }
}

impl Drop for Envelope {
    fn drop(&mut self) {
        self.budget.used.fetch_sub(self.frame.len(), Relaxed);
        self.budget
            .metrics
            .queued_bytes
            .fetch_sub(self.frame.len(), Relaxed);
    }
}

impl Peer {
    pub(crate) fn close(&self, reason: Disconnect) -> bool {
        if self.closing.swap(true, Relaxed) {
            return false;
        }
        self.output.close(reason);
        true
    }

    fn enqueue(&self, bytes: &Bytes) -> Result<(), Disconnect> {
        self.enqueue_frame(&Frame::encoded(bytes.clone()))
    }

    fn enqueue_frame(&self, frame: &Frame) -> Result<(), Disconnect> {
        if self.closing.load(Relaxed) {
            return Ok(());
        }
        let size = frame.len();
        if self
            .budget
            .used
            .fetch_update(Relaxed, Relaxed, |used| {
                used.checked_add(size)
                    .filter(|&next| next <= self.budget.limit)
            })
            .is_err()
        {
            self.overloaded();
            return Ok(());
        }
        if self
            .budget
            .metrics
            .queued_bytes
            .fetch_update(Relaxed, Relaxed, |used| {
                used.checked_add(size)
                    .filter(|&next| next <= self.budget.global_limit)
            })
            .is_err()
        {
            self.budget.used.fetch_sub(size, Relaxed);
            self.budget.metrics.global_pressure.fetch_add(1, Relaxed);
            return Err(Disconnect::OVERLOADED);
        }
        let packet = Envelope {
            frame: frame.clone(),
            budget: self.budget.clone(),
        };
        if !self.output.send(packet) {
            self.overloaded();
        }
        Ok(())
    }

    fn overloaded(&self) {
        if self.close(Disconnect::OVERLOADED) {
            self.budget.metrics.slow_consumers.fetch_add(1, Relaxed);
        }
    }
}

pub(crate) struct Registration {
    pub peer: Arc<Peer>,
    relay: Arc<Relay>,
}

impl Drop for Registration {
    fn drop(&mut self) {
        self.relay.remove(&self.peer);
    }
}

#[cfg(test)]
pub(crate) struct Subscription {
    pub registration: Registration,
    pub outgoing: mpsc::Receiver<Envelope>,
    pub close: watch::Receiver<Option<Disconnect>>,
}

#[derive(Serialize)]
pub struct ChannelInfo {
    pub name: Option<String>,
    pub name_base64: String,
    pub members: usize,
    pub variables: usize,
    pub variable_bytes: usize,
}

/// Registry names are bounded to 16 bytes. Inline inspection names hold small
/// metadata without per-name allocation or reference-count traffic.
struct SnapshotName {
    bytes: [u8; 16],
    len: u8,
}

impl SnapshotName {
    fn new(name: &[u8]) -> Self {
        let mut bytes = [0; 16];
        bytes[..name.len()].copy_from_slice(name);
        Self {
            bytes,
            len: name.len() as u8,
        }
    }

    fn as_bytes(&self) -> &[u8] {
        &self.bytes[..usize::from(self.len)]
    }
}

/// One coherent view owns only small names and numeric metadata. It keeps no
/// registry guard, peer or variable value alive while inspection formats output.
struct ChannelSnapshot {
    name: SnapshotName,
    members: usize,
    variables: usize,
    variable_bytes: usize,
}

impl Relay {
    pub fn new(config: Config) -> Result<Arc<Self>> {
        config.validate()?;
        // Verify entropy availability before listening, never silently use predictable IDs.
        let _ = random_id()?;
        let mut channels = HashMap::new();
        channels.insert(Bytes::from_static(GLOBAL_CHANNEL), Channel::default());
        let read_budget = (config.total_read_buffer_bytes > 0).then(|| {
            tokio_tungstenite::tungstenite::protocol::ReadBudget::new(
                config.total_read_buffer_bytes,
            )
        });
        Ok(Arc::new(Self {
            config,
            metrics: Arc::new(Metrics {
                read_budget,
                ..Metrics::default()
            }),
            draining: AtomicBool::new(false),
            stopping: AtomicBool::new(false),
            state: RwLock::new(Registry {
                users: HashMap::new(),
                channels,
                listeners: Default::default(),
                next_key: 1,
                sessions: 0,
            }),
        }))
    }

    pub fn counts(&self) -> (usize, usize) {
        let state = self.state.read();
        (state.sessions, state.channels.len())
    }

    pub(crate) fn begin_shutdown(&self) {
        self.draining.store(true, Relaxed);
        self.stopping.store(true, Relaxed);
    }

    fn channel_snapshot(&self) -> Vec<ChannelSnapshot> {
        let state = self.state.read();
        state
            .channels
            .iter()
            .map(|(name, channel)| ChannelSnapshot {
                name: SnapshotName::new(name),
                members: channel.members.len(),
                variables: channel.variables.len(),
                variable_bytes: channel.variable_bytes,
            })
            .collect()
    }

    fn channel_members_snapshot(&self) -> Vec<(SnapshotName, usize)> {
        let state = self.state.read();
        state
            .channels
            .iter()
            .map(|(name, channel)| (SnapshotName::new(name), channel.members.len()))
            .collect()
    }

    pub fn channels(&self) -> Vec<ChannelInfo> {
        let mut channels: Vec<_> = self
            .channel_snapshot()
            .into_iter()
            .map(|channel| ChannelInfo {
                name: std::str::from_utf8(channel.name.as_bytes())
                    .ok()
                    .map(str::to_owned),
                name_base64: STANDARD.encode(channel.name.as_bytes()),
                members: channel.members,
                variables: channel.variables,
                variable_bytes: channel.variable_bytes,
            })
            .collect();
        channels.sort_unstable_by(|a, b| a.name_base64.cmp(&b.name_base64));
        channels
    }

    pub fn disconnect(&self, id: u64) -> bool {
        self.state.read().users.get(&id).is_some_and(|p| {
            p.close(Disconnect {
                code: 4000,
                reason: "Administrative Disconnect",
            })
        })
    }

    #[cfg(test)]
    fn subscribe(self: &Arc<Self>, channel: &[u8]) -> Result<Subscription, Disconnect> {
        let (outgoing, receiver) = mpsc::channel(self.config.queue_messages);
        let (close, close_receiver) = watch::channel(None);
        let registration =
            self.subscribe_with_output(channel, Arc::new(AsyncOutput { outgoing, close }))?;
        Ok(Subscription {
            registration,
            outgoing: receiver,
            close: close_receiver,
        })
    }

    pub(crate) fn subscribe_with_output(
        self: &Arc<Self>,
        channel: &[u8],
        output: Arc<dyn PeerOutput>,
    ) -> Result<Registration, Disconnect> {
        if channel.len() > 16 {
            return Err(Disconnect::CHANNEL_LENGTH);
        }
        let mut state = self.state.write();
        if self.draining.load(Relaxed)
            || state.sessions >= self.config.max_connections
            || (!state.channels.contains_key(channel)
                && state.channels.len() >= self.config.max_channels)
            || state
                .channels
                .get(channel)
                .is_some_and(|c| c.members.len() >= self.config.max_channel_members)
        {
            self.metrics.rejected.fetch_add(1, Relaxed);
            return Err(Disconnect::OVERLOADED);
        }
        let id = loop {
            let id = random_id().map_err(|_| Disconnect::OVERLOADED)?;
            if id != 0 && id != BROADCAST && !state.users.contains_key(&id) {
                break id;
            }
        };
        let key = state.next_key;
        state.next_key = key.checked_add(1).ok_or(Disconnect::OVERLOADED)?;
        let peer = Arc::new(Peer {
            key,
            id: AtomicU64::new(id),
            channel: Bytes::copy_from_slice(channel),
            authenticated: AtomicBool::new(false),
            listener: AtomicU8::new(0),
            closing: AtomicBool::new(false),
            output,
            budget: Arc::new(Budget {
                used: AtomicUsize::new(0),
                limit: self.config.queue_bytes,
                global_limit: self.config.total_queue_bytes,
                metrics: self.metrics.clone(),
            }),
        });
        // Publish only after the welcome packet is first in this session's FIFO.
        peer.enqueue(&protocol::uint(id))?;
        state.users.insert(id, peer.clone());
        state
            .channels
            .entry(peer.channel.clone())
            .or_default()
            .members
            .insert(key, peer.clone());
        state.sessions += 1;
        self.metrics.joined.fetch_add(1, Relaxed);
        Ok(Registration {
            peer,
            relay: self.clone(),
        })
    }

    #[cfg(test)]
    pub(crate) fn receive(&self, peer: &Peer, bytes: Bytes) -> Result<(), Disconnect> {
        let capacity = self.config.read_buffer_bytes.max(bytes.len());
        self.receive_with_storage(peer, bytes, capacity)
    }

    pub(crate) fn receive_with_storage(
        &self,
        peer: &Peer,
        bytes: Bytes,
        storage_capacity: usize,
    ) -> Result<(), Disconnect> {
        if peer.closing.load(Relaxed) {
            return Ok(());
        }
        self.metrics.incoming_messages.fetch_add(1, Relaxed);
        self.metrics
            .incoming_bytes
            .fetch_add(bytes.len() as u64, Relaxed);
        let (target, value) = protocol::parse(&bytes)?;
        if target == 0 {
            return self.control(peer, value);
        }
        let state = self.state.read();
        if peer.closing.load(Relaxed) {
            return Ok(());
        }
        let private_recipient = if target == BROADCAST {
            if peer.channel.as_ref() == GLOBAL_CHANNEL
                && self.config.disable_global_broadcast
                && !peer.authenticated.load(Relaxed)
            {
                return Err(Disconnect {
                    code: 1008,
                    reason: "Global Broadcast Requires Authentication",
                });
            }
            None
        } else {
            match state.users.get(&target) {
                Some(recipient) => Some(recipient),
                None => return Ok(()),
            }
        };
        let value_start = bytes.len() - value.len();
        let compact = storage_capacity > self.config.read_buffer_bytes
            && bytes.len().saturating_mul(8) < storage_capacity
            && !bytes.is_unique();
        let frame = Frame::routed(peer.id.load(Relaxed), bytes, value_start, compact);
        let counter = if compact {
            &self.metrics.routing_copied_bytes
        } else {
            &self.metrics.routing_reused_bytes
        };
        counter.fetch_add(frame.payload().len() as u64, Relaxed);
        if let Some(recipient) = private_recipient
            && state.listeners(PRIVATE_MESSAGE).is_empty()
        {
            // Lookup and sender identity form one registry snapshot. The
            // retained target owns its lifetime through the socket write.
            let recipient = recipient.clone();
            drop(state);
            return recipient.enqueue_frame(&frame);
        }
        if target == BROADCAST {
            if peer.channel.as_ref() == GLOBAL_CHANNEL {
                for recipient in state.users.values() {
                    if recipient.key != peer.key {
                        recipient.enqueue_frame(&frame)?;
                    }
                }
            } else {
                if let Some(channel) = state.channels.get(&peer.channel) {
                    for recipient in channel.members.values() {
                        if recipient.key != peer.key {
                            recipient.enqueue_frame(&frame)?;
                        }
                    }
                }
                for recipient in state.listeners(CHANNEL_MESSAGE) {
                    recipient.enqueue_frame(&frame)?;
                }
            }
        } else if let Some(recipient) = private_recipient {
            recipient.enqueue_frame(&frame)?;
            for listener in state.listeners(PRIVATE_MESSAGE) {
                if listener.key != recipient.key {
                    listener.enqueue_frame(&frame)?;
                }
            }
        }
        Ok(())
    }

    fn control(&self, peer: &Peer, value: &[u8]) -> Result<(), Disconnect> {
        match protocol::command(value)? {
            Command::Authenticate(password) => {
                if protocol::secret_matches(self.config.auth_password.as_deref(), password) {
                    peer.authenticated.store(true, Relaxed);
                }
                peer.enqueue(&protocol::reply(
                    0,
                    &[if peer.authenticated.load(Relaxed) {
                        0xf5
                    } else {
                        0xf4
                    }],
                ))?;
            }
            Command::Listen(flags) => {
                if !peer.authenticated.load(Relaxed) {
                    return self.unauthorized();
                }
                if peer.channel.as_ref() == GLOBAL_CHANNEL {
                    let mut state = self.state.write();
                    if peer.closing.load(Relaxed) {
                        return Ok(());
                    }
                    state.set_listener_flags(peer, flags & 7);
                } else {
                    peer.listener.store(flags & 7, Relaxed);
                }
                peer.enqueue(&protocol::reply(1, &protocol::uint(u64::from(flags & 7))))?;
            }
            Command::Channels => {
                if !peer.authenticated.load(Relaxed) {
                    return self.unauthorized();
                }
                let mut channels = self.channel_members_snapshot();
                channels.sort_unstable_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));
                let mut e = Encoder::new(Vec::new());
                e.array(channels.len() as u64).expect("Vec encoding");
                for (name, members) in channels {
                    e.array(2)
                        .and_then(|e| e.bytes(name.as_bytes()))
                        .and_then(|e| e.u64(members as u64))
                        .expect("Vec encoding");
                }
                peer.enqueue(&protocol::reply(2, &e.into_writer()))?;
            }
            Command::Assign(id) => {
                if !peer.authenticated.load(Relaxed) {
                    return self.unauthorized();
                }
                if id == 0 || id == BROADCAST {
                    return Err(Disconnect::RESERVED);
                }
                let mut state = self.state.write();
                let old = peer.id.load(Relaxed);
                // Takeover may have happened after receive's initial closing check.
                // The map entry must still belong to this immutable session key.
                if peer.closing.load(Relaxed)
                    || state
                        .users
                        .get(&old)
                        .is_none_or(|owner| owner.key != peer.key)
                {
                    return Ok(());
                }
                if old != id {
                    let owner = state.users.remove(&old).ok_or(Disconnect::PROTOCOL)?;
                    if let Some(previous) = state.users.insert(id, owner) {
                        previous.close(Disconnect::TAKEN);
                        shrink_sparse_map(&mut state.users);
                    }
                    peer.id.store(id, Relaxed);
                }
                peer.enqueue(&protocol::reply(3, &protocol::uint(id)))?;
            }
            Command::SetVariable { key, value } => {
                let mut state = self.state.write();
                if peer.closing.load(Relaxed) {
                    return Ok(());
                }
                let channel = state
                    .channels
                    .get_mut(&peer.channel)
                    .ok_or(Disconnect::PROTOCOL)?;
                let previous_size = channel
                    .variables
                    .get(key)
                    .map_or(0, |v| key.len() + v.len());
                let next = channel.variable_bytes - previous_size + key.len() + value.len();
                let total = self.metrics.variable_bytes.load(Relaxed) - previous_size
                    + key.len()
                    + value.len();
                if next > self.config.max_variable_bytes
                    || total > self.config.total_variable_bytes
                    || (previous_size == 0 && channel.variables.len() >= self.config.max_variables)
                {
                    return Err(Disconnect::OVERLOADED);
                }
                // Copy the retained value, so a tiny variable cannot pin a large input frame.
                channel
                    .variables
                    .insert(Bytes::copy_from_slice(key), Bytes::copy_from_slice(value));
                channel.variable_bytes = next;
                self.metrics.variable_bytes.store(total, Relaxed);
                peer.enqueue(&protocol::reply(4, &[0xf5]))?;
            }
            Command::GetVariable(key) => {
                let state = self.state.read();
                let value = state
                    .channels
                    .get(&peer.channel)
                    .and_then(|c| c.variables.get(key));
                let mut found = Vec::with_capacity(3 + value.map_or(1, Bytes::len));
                found.extend_from_slice(&[0x82, if value.is_some() { 0xf5 } else { 0xf4 }]);
                found.extend_from_slice(value.map_or(&[0xf6][..], Bytes::as_ref));
                peer.enqueue(&protocol::reply(200, &found))?;
            }
        }
        Ok(())
    }

    fn unauthorized(&self) -> Result<(), Disconnect> {
        Err(Disconnect {
            code: 1008,
            reason: "Authentication Required",
        })
    }

    fn remove(&self, peer: &Peer) {
        let mut state = self.state.write();
        let Some(channel) = state.channels.get_mut(&peer.channel) else {
            return;
        };
        if channel.members.remove(&peer.key).is_none() {
            return;
        }
        peer.closing.store(true, Relaxed);
        let id = peer.id.load(Relaxed);
        let notify = !self.stopping.load(Relaxed);
        let frame = notify.then(|| protocol::envelope(BROADCAST, &protocol::uint(id)));
        if let Some(frame) = &frame {
            for recipient in channel.members.values() {
                let _ = recipient.enqueue(frame);
            }
        }
        if channel.members.is_empty() && peer.channel.as_ref() != GLOBAL_CHANNEL {
            self.metrics
                .variable_bytes
                .fetch_sub(channel.variable_bytes, Relaxed);
            state.channels.remove(&peer.channel);
            shrink_sparse_map(&mut state.channels);
        } else {
            // Empty ordinary rooms drop the complete map; retained rooms and
            // the persistent global room can release spare membership slots.
            shrink_sparse_map(&mut channel.members);
        }
        if peer.channel.as_ref() == GLOBAL_CHANNEL {
            state.set_listener_flags(peer, 0);
        }
        if notify && peer.channel.as_ref() != GLOBAL_CHANNEL {
            for recipient in state.listeners(DISCONNECT_MESSAGE) {
                let _ = recipient.enqueue(frame.as_ref().expect("notifications enabled"));
            }
        }
        // A displaced session must never erase the new owner of its previous ID.
        if state
            .users
            .get(&id)
            .is_some_and(|owner| owner.key == peer.key)
        {
            state.users.remove(&id);
            shrink_sparse_map(&mut state.users);
        }
        state.sessions -= 1;
        self.metrics.disconnected.fetch_add(1, Relaxed);
    }
}

fn random_id() -> Result<u64> {
    let mut bytes = [0; 8];
    getrandom::fill(&mut bytes).context("operating system entropy unavailable")?;
    Ok(u64::from_ne_bytes(bytes))
}

