            relay
                .receive(
                    &peer,
                    protocol::request(0, &protocol::text("test-password")),
                )
                .unwrap();
            subscriptions[i].outgoing.try_recv().unwrap();
            relay
                .receive(&peer, protocol::request(3, &protocol::uint(id)))
                .unwrap();
